static List<String> readPage(Path plik, int numerStrony, int liniiNaStrone) throws IOException {
    int skip = (numerStrony - 1) * liniiNaStrone;
    List<String> result = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(plik.toFile()))) {
        String linia;
        int index = 0;
        while ((linia = br.readLine()) != null) {
            if (index >= skip && index < skip + liniiNaStrone) {
                result.add(linia);
            }
            index++;
            if (index >= skip + liniiNaStrone) break;
        }
    }
    return result;
}

