try (BufferedWriter bw = new BufferedWriter(new FileWriter(plik.toFile()))) {
    bw.write("# To jest komentarz"); bw.newLine();
    bw.write("host=localhost"); bw.newLine();
    bw.write(""); bw.newLine();
    bw.write("# Kolejny komentarz"); bw.newLine();
    bw.write("port=8080"); bw.newLine();
}

Map<String, String> config = new LinkedHashMap<>();
try (BufferedReader br = new BufferedReader(new FileReader(plik.toFile()))) {
    String linia;
    while ((linia = br.readLine()) != null) {
        linia = linia.trim();
        if (linia.isEmpty() || linia.startsWith("#")) continue;
        String[] parts = linia.split("=", 2);
        config.put(parts[0], parts[1]);
    }
}
config.forEach((k, v) -> System.out.println(k + " = " + v));

Path plik = Files.createTempFile("lesson03_ex30_", ".txt");
try (BufferedWriter bw = new BufferedWriter(new FileWriter(plik.toFile()))) {
    for (int i = 0; i < 10_000; i++) {
        bw.write("java kod test przyklad java test");
        bw.newLine();
    }
}

long start = System.nanoTime();
Map<String, Integer> counts = new HashMap<>();
try (BufferedReader br = new BufferedReader(new FileReader(plik.toFile()))) {
    String linia;
    while ((linia = br.readLine()) != null) {
        for (String word : linia.split("\\s+")) {
            if (!word.isEmpty()) counts.merge(word, 1, Integer::sum);
        }
    }
}

Path report = Files.createTempFile("lesson03_ex30_report_", ".txt");
try (BufferedWriter bw = new BufferedWriter(new FileWriter(report.toFile()))) {
    counts.entrySet().stream()
            .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
            .forEach(e -> {
                try {
                    bw.write(e.getKey() + ": " + e.getValue());
                    bw.newLine();
                } catch (IOException ex) { throw new RuntimeException(ex); }
            });
}
long czas = (System.nanoTime() - start) / 1_000_000;
System.out.println("Czas przetwarzania: " + czas + "ms");
System.out.println(Files.readString(report));
